              "Drenajsız kayma dayanımı çalışma aralığı: 15 kPa ≤ c_u ≤ 50 kPa (Kritik sınır: c_u < 15 kPa durumunda radyal çevreleme/destek gerilmesi σ_radial = 4 c_u yetersiz kaldığından gövde şişmesi / bulging göçmesi meydana gelir; geosentetik kılıflı taş kolon - GEC/GSC - zorunlu hale gelir. c_u > 50 kPa durumunda ise konvansiyonel temel sistemleri ekonomik olarak devreye girer).",
              "Tane eğrisi: Taş kolon imalatında kullanılan kırmataş gradasyonu 10 - 40 mm veya 20 - 50 mm, C_u < 3, aşınma kaybı (Los Angeles) <%25, yassılık indeksi <%20 olmalıdır.",
              "**Jet Grout (Yüksek Basınçlı Enjeksiyon):**",
              "**Kriterler:** D_10 sınırından bağımsız olarak çakıldan yüksek plastisiteli kile (CH) ve organik zeminlere kadar tüm litolojilerde çalışır.",
              "Jet Grout 1 (Monojet, 300-500 bar çimento şerbeti), Jet Grout 2 (Bijet, çimento şerbeti + koaksiyel hava), Jet Grout 3 (Trijet, yüksek basınçlı su + hava ile kesme, alt nozuldan düşük basınçlı çimento dolgusu).",
              "Kohezyonsuz zeminlerde zemin taneleri çimento matrisi içine hapsedilerek q_u = 5 - 15 MPa dayanımlı \"soil-cement\" kolon elde edilirken; kohezyonlu killerde kesme enerjisi kil bloklarını aşındırır, kısmi yerdeğiştirme ile q_u = 1.5 - 5.0 MPa kolon elde edilir.",
              "**Derin Zemin Karıştırma (Deep Soil Mixing - DSM):**",
              "**Kriterler:** Düşük mukavemetli kohezyonlu zeminler (c_u ≤ 40 kPa), gevşek siltler ve siltli kumlar (N_SPT < 10).",
              "Dane boyutu kısıtı: Maksimum tane boyutu karıştırıcı burgu ve pabuçların dönüşünü engellememek için d_max < 50 mm olmalıdır (iri çakıllı/bloklu birimlerde uygulanamaz).",
              "Jet Grouta göre malzeme geri dönüş zayiatı (slurry/spoil) %5 - %15 mertebesindedir (Jet Grout'ta bu oran %40 - %100'e çıkabilir). Homojenlik bağlayıcı hacmi kontrolü ile tam optimize edilir.",
