            type: "paragraph",
            content: "**Davisson Göçme Kriteri (Limit Yük Tayini)** Kazığın nihai limit taşıma yükü (Q_ult), toplam baş oturmasının (S_t) elastik kısalma sınırını aştığı nokta olarak tanımlanır:"
